<?php $isEitaa=$channel==='eitaa';$states=['expired'=>'مهلت ارسال گذشته','pending'=>'در صف ارسال','sending'=>'در حال ارسال','sent'=>'پذیرفته‌شده توسط ایتا','provider_accepted'=>'پذیرفته‌شده توسط پیامک','rejected'=>'سرویس ارسال را نپذیرفت','provider_rejected'=>'پیامک پذیرفته نشد','unknown'=>'نتیجه نیازمند بررسی','unverified_response'=>'پاسخ سرویس نیازمند بررسی','submission_uncertain'=>'نتیجه نامشخص؛ تکرار نشده','permission_required'=>'نیازمند اجازهٔ مخاطب','not_linked'=>'اتصال مخاطب در دسترس نیست','disabled'=>'ارسال غیرفعال است']; ?>
<header class="admin-page-heading"><div><span class="eyebrow">ارتباط با مخاطبان مرشد</span><h1>مرکز پیام‌ها</h1><p class="muted">مخاطب را انتخاب کن، پیام بنویس و نتیجهٔ ارسال را ببین.</p></div><span class="tag"><?= $channelEnabled?'اتصال فعال':'نیازمند تنظیم اتصال' ?></span></header>
<nav class="messaging-tabs" aria-label="کانال ارسال پیام"><a class="secondary" <?= $isEitaa?'aria-current="page"':'' ?> href="<?= $this->h($this->url('/messages?channel=eitaa')) ?>"><?= $this->icon('chat') ?>پیام ایتا</a><a class="secondary" <?= !$isEitaa?'aria-current="page"':'' ?> href="<?= $this->h($this->url('/messages?channel=sms')) ?>"><?= $this->icon('chat') ?>پیامک TSMS</a></nav>
<div class="messaging-workspace"><section class="card"><h2>انتخاب مخاطبان</h2><p class="small muted"><?= $isEitaa?'افراد متصل به ایتا اینجا دیده می‌شوند. ارسال پیام دستی برای کسانی فعال است که اجازهٔ دریافت پیام را ثبت کرده‌اند.':'فقط حساب‌های فعال با شمارهٔ تأییدشده نشان داده می‌شوند. پیام‌های مرتبط با جلسه را برای مخاطب انتخاب‌شده بفرستید.' ?></p><form method="get" action="<?= $this->h($this->url('/messages')) ?>"><?php if(!($this->config['pretty_urls']??false)): ?><input type="hidden" name="r" value="/messages"><?php endif; ?><input type="hidden" name="channel" value="<?= $channel ?>"><div class="search"><input type="search" name="q" maxlength="160" value="<?= $this->h(is_string($_GET['q']??null)?$_GET['q']:'') ?>" placeholder="جست‌وجوی نام، نام کاربری یا شماره" aria-label="جست‌وجوی مخاطب"><button class="secondary">جست‌وجو</button></div></form>
<?= $this->start('/messages/send') ?><input type="hidden" name="channel" value="<?= $channel ?>"><input type="hidden" name="request_id" value="<?= \Morshed\Core\Security::id() ?>"><div class="recipient-picker"><div class="recipient-toolbar"><input type="search" data-recipient-search placeholder="پیداکردن در این فهرست" aria-label="فیلتر همین فهرست"><span class="small muted" data-recipient-count>۰ مخاطب انتخاب شده</span></div><div class="recipient-list" data-recipient-list><?php foreach($contacts as $person):$selectable=!$isEitaa||!empty($person['eitaa_allowed']); ?><label class="recipient-row" data-recipient-row><input type="checkbox" name="user_ids[]" value="<?= $this->h($person['id']) ?>" <?= $selectable?'':'disabled' ?> <?= in_array($person['id'],$this->old['user_ids']??[],true)?'checked':'' ?>><span><strong><?= $this->h($person['display_name']?:($person['username']?:'حساب متصل به ایتا')) ?></strong><small><?= $this->h($person['username']?:'بدون نام کاربری') ?><?= !$isEitaa?' · '.$this->h($person['phone_hint']):'' ?></small></span><span class="tag"><?= $isEitaa?($selectable?'اجازهٔ پیام فعال':'منتظر اجازهٔ مخاطب'):'شماره تأییدشده' ?></span></label><?php endforeach; ?><?php if(!$contacts): ?><p class="empty muted">مخاطبی با این مشخصات پیدا نشد.</p><?php endif; ?></div></div><p class="small muted">در هر ارسال حداکثر ۲۰ مخاطب انتخاب کنید.</p><?= $this->field('title','عنوان پیام','text','',true,180) ?><label>متن پیام<textarea name="body" rows="5" maxlength="1000" required placeholder="مثلاً: جلسهٔ مشاورهٔ شما روز … ساعت … برگزار می‌شود."><?= $this->val('body') ?></textarea></label><button <?= $channelEnabled?'':'disabled' ?>><?= $isEitaa?'ارسال پیام ایتا':'ارسال پیامک به مخاطبان انتخاب‌شده' ?></button></form>
<nav class="row section" aria-label="صفحه‌بندی مخاطبان"><?php $q=is_string($_GET['q']??null)?$_GET['q']:'';if($recipientPage>1): ?><a class="secondary" href="<?= $this->h($this->url('/messages?'.http_build_query(['channel'=>$channel,'q'=>$q,'page'=>$recipientPage-1]))) ?>">مخاطبان قبلی</a><?php endif; ?><span class="small muted">صفحه <?= $this->number($recipientPage) ?></span><?php if($hasMore): ?><a class="secondary" href="<?= $this->h($this->url('/messages?'.http_build_query(['channel'=>$channel,'q'=>$q,'page'=>$recipientPage+1]))) ?>">مخاطبان بعدی</a><?php endif; ?></nav></section>
<aside class="card"><div class="section-head"><h2>نتیجهٔ ارسال‌ها</h2><span class="tag"><?= $this->number(count($rows)) ?> مورد اخیر</span></div><p class="small muted">تأیید درخواست و یادآوری جلسات نیز در این فهرست ثبت می‌شوند. پذیرش سرویس به‌تنهایی تضمین رسیدن پیام به دستگاه مخاطب نیست.</p><?= $this->start('/messages/process') ?><input type="hidden" name="channel" value="<?= $channel ?>"><button class="secondary" <?= $channelEnabled?'':'disabled' ?>>ارسال موارد در صف</button></form><div class="table-scroll section"><table class="message-history"><thead><tr><th>مخاطب و پیام</th><th>وضعیت</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong><?= $this->h($row['display_name']) ?></strong><br><?= $this->h($row['title']) ?></td><td><span class="tag"><?= $this->h($states[$row['state']]??'نیازمند بررسی') ?></span></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="2" class="muted">هنوز پیامی ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div></aside></div>
